import { tv, type VariantProps } from "@/lib/beton/tv";

export const emptyState = tv({
  slots: {
    root: "flex w-full flex-col items-center justify-center gap-4 border-3 border-dashed border-border bg-raised text-center",
    icon: "flex items-center justify-center border-3 border-border bg-secondary",
    title: "font-display font-black tracking-tight text-foreground",
    description: "max-w-prose text-foreground",
    actions: "flex flex-wrap items-center justify-center gap-3 pt-2",
  },
  variants: {
    size: {
      sm: { root: "p-6", icon: "size-12", title: "text-h4", description: "text-sm" },
      md: { root: "p-10", icon: "size-16", title: "text-h3", description: "text-base" },
      lg: { root: "p-16", icon: "size-20", title: "text-h2", description: "text-lg" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type EmptyStateVariants = VariantProps<typeof emptyState>;

import { emptyState, type EmptyStateVariants } from "@/lib/beton/recipes/empty-state.recipe";
import type { ComponentProps, ReactNode } from "react";

export interface EmptyStateProps extends Omit<ComponentProps<"div">, "title">, EmptyStateVariants {
  /** What is missing, in a few words. */
  title: ReactNode;
  /** Why it is missing, or what to do about it. */
  description?: ReactNode;
  /** A mark above the title. Decorative: it is hidden from screen readers. */
  icon?: ReactNode;
  /** Buttons under the text. */
  actions?: ReactNode;
  /** The heading level the title takes. Defaults to h3. */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
}

/** What to show where there is nothing yet: no results, no records, no files. */
export function EmptyState({
  size = "md",
  title,
  description,
  icon,
  actions,
  headingLevel = 3,
  className,
  children,
  ...props
}: EmptyStateProps) {
  const styles = emptyState({ size });
  const Heading = `h${headingLevel}` as const;
  return (
    <div {...props} className={styles.root({ class: className })}>
      {icon ? (
        <span aria-hidden="true" className={styles.icon()}>
          {icon}
        </span>
      ) : null}
      <Heading className={styles.title()}>{title}</Heading>
      {description ? <p className={styles.description()}>{description}</p> : null}
      {children}
      {actions ? <div className={styles.actions()}>{actions}</div> : null}
    </div>
  );
}
